var e=document.querySelector(`#refresh-page`),t=document.querySelector(`#status`);e?.addEventListener(`click`,async()=>{e.disabled=!0,t&&(t.textContent=`正在重新加载插件并刷新页面…`);try{let[e]=await chrome.tabs.query({active:!0,currentWindow:!0});if(e?.id===void 0)throw Error(`未找到当前页面`);await chrome.scripting.executeScript({target:{tabId:e.id},world:`MAIN`,func:()=>{window.setTimeout(()=>window.location.reload(),600)}}),chrome.runtime.reload()}catch{e.disabled=!1,t&&(t.textContent=`重新加载失败，请重试`)}});